export function ticketPrice(age, day) {
  const base = isWeekend(day) ? 12 : 10;

  if (age < 12) {
    function discount(price) {
      return price / 2;
    }
  } else if (age >= 65) {
    function discount(price) {
      return price - 3;
    }
  } else {
    function discount(price) {
      return price;
    }
  }

  const isWeekend = (name) => name === "sat" || name === "sun";

  return discount(base);
}
